        getChartData(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.PRODUCTS.length - 1);
            var product = this.PRODUCTS[idx];
            var demandTable = this._getDemandTable(product, state);

            var priceLabels = product.priceOptions.map(function(p) { return 'ARS $' + p.toLocaleString(); });
            var cmData = product.priceOptions.map(function(p) {
                var d = demandTable[p] || 0;
                return (p - product.variableCost) * d;
            });

            this._labelCharts();
            return {
                demandChart: {
                    labels: priceLabels,
                    datasets: [{ label: this._chartText('chart_demand_ds'), data: cmData }]
                },
                contributionChart: {
                    labels: state.domainState.productLabels,
                    datasets: [{ label: this._chartText('chart_contrib_ds'), data: state.domainState.contributionHistory }]
                }
            };
        }

        formatCompletionMessage(summary) {
            var _t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : (summary.score || 0);
            var grade = summary.grade || this._letter(score);
            var tier = summary.performanceTier || summary.performance || '';
            var label = _t('tier_' + tier);
            var feedback = summary.feedbackKey ? _t(summary.feedbackKey) : '';
            var insights = summary.insights || [];
            var items = ''; for (var i = 0; i < insights.length; i++) { items += '<li>' + _t(insights[i]) + '</li>'; }
            var cm = (typeof summary.totalContribution === 'number') ? Math.round(summary.totalContribution) : 0;
            return '<div class="nf-cm">' + '<div class="nf-cm-title">' + _t('cm_title') + '</div>' + '<div class="nf-cm-score">' + score + '<span class="nf-cm-den">/100</span></div>' + '<div class="nf-cm-grade">' + _t('cm_grade') + ': <strong>' + grade + '</strong></div>' + '<div class="nf-cm-verdict">' + label + '</div>' + (feedback ? '<div class="nf-cm-feedback">' + feedback + '</div>' : '') + '<div class="nf-cm-sub">' + _t('cm_contribution') + ': $' + cm.toLocaleString() + '</div>' + (items ? '<div class="nf-cm-insights"><div class="nf-cm-insights-h">' + _t('cm_insights') + '</div><ul>' + items + '</ul></div>' : '') + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;

            var idx = Math.min((state.currentPeriod || 1) - 1, this.PRODUCTS.length - 1);
            var product = this.PRODUCTS[idx];

            if (!results.withinWTP) {
                return window.mySimulation.t('hint_outside_wtp');
            }

            if (results.price === product.optimalProfitPrice) {
                return window.mySimulation.t('hint_optimal');
            }

            if (product.id === 'espresso' && results.price >= 950) {
                return window.mySimulation.t('hint_espresso_high');
            }

            if (product.id === 'coldBrew' && results.price <= 950) {
                return window.mySimulation.t('hint_coldbrew_low');
            }

            return null;
        }

