        getPerformanceSummary(history) {
            if (!history.length) return {};

            var totalCM = 0;
            var totalScore = 0;
            var productResults = [];

            for (var i = 0; i < history.length; i++) {
                var r = history[i].results;
                if (r) {
                    totalCM += r.totalCM || 0;
                    totalScore += r.periodScore || 0;
                    productResults.push(r);
                }
            }

            var optimalEspresso = (750 - 420) * 280;
            var optimalSingle = (1200 - 680) * 95;
            var optimalColdBrew = (1800 - 420) * 120;
            var optimalTotal = optimalEspresso + optimalSingle + optimalColdBrew;

            var costPlusEspresso = (672 - 420) * 350;
            var costPlusSingle = (1088 - 680) * 120;
            var costPlusColdBrew = (672 - 420) * 185;
            var costPlusTotal = costPlusEspresso + costPlusSingle + costPlusColdBrew;

            var performance = 'beginner';
            var feedbackKey = 'feedback_beginner';
            if (totalScore >= 85) { performance = 'estratega'; feedbackKey = 'feedback_estratega'; }
            else if (totalScore >= 70) { performance = 'good'; feedbackKey = 'feedback_good'; }
            else if (totalScore >= 55) { performance = 'review'; feedbackKey = 'feedback_review'; }

            var insights = [];
            if (totalCM >= optimalTotal * 0.9) {
                insights.push('near_optimal_insight');
            }
            if (totalCM < costPlusTotal) {
                insights.push('below_costplus_insight');
            }

            return {
                totalContribution: totalCM,
                optimalContribution: optimalTotal,
                costPlusContribution: costPlusTotal,
                score: Math.round(totalScore),
                overallScore: Math.max(0, Math.min(100, Math.round(totalScore))),
                grade: this._letter(Math.max(0, Math.min(100, Math.round(totalScore)))),
                performanceTier: performance,
                performance: performance,
                feedbackKey: feedbackKey,
                insights: insights
            };
        }

